const P = api.body('predator'); const prey = []; const R = 6;
const place = o => { const r = R * Math.sqrt(api.rand()), t = 2 * Math.PI * api.rand(); o.position.set(r * Math.cos(t), 0.18, r * Math.sin(t)); };
for (let i = 0; i < Math.round(api.param('H')); i++) { const o = api.spawn({ shape: { kind: 'sphere', r: 0.16 }, material: { preset: 'plastic', color: '#f2e2b8' } }); place(o); prey.push(o); }
let handling = 0, eaten = 0, tHand = 0, target = null; const dir = api.V3(1, 0, 0);
api.label('prey', () => prey[0] && prey[0].position, 'One of the prey: eaten prey are replaced, so the density stays H.');
api.onFrame((dt, t) => {
  if (handling > 0) { handling -= dt; tHand += dt; if (handling <= 0) api.event('handling done: back to searching', P.position, { id: 'search' }); return; }
  if (!target || !target.visible) target = prey.reduce((b, o) => !b || o.position.distanceTo(P.position) < b.position.distanceTo(P.position) ? o : b, null);
  if (!target) return; dir.copy(target.position).sub(P.position); dir.y = 0; const d = dir.length();
  if (d < 0.3) { eaten++; handling = api.param('Th'); place(target); target = null; api.event('catch: handling for ' + api.fmt(api.param('Th')) + ' s', P.position, { id: 'catch' }); return; }
  dir.normalize(); P.position.addScaledVector(dir, Math.min(d, api.param('a') * dt)); P.rotation.z = Math.atan2(dir.x, dir.z);
});
api.readout('catches per minute', () => api.time() > 1 ? api.fmt(eaten / api.time() * 60) : '—');
api.readout('share of time handling', () => api.time() > 1 ? api.fmt(tHand / api.time() * 100) + ' %' : '—');
api.readout('ceiling 60 / Th', () => api.fmt(60 / api.param('Th')) + ' per min');
api.plot('catches', () => eaten);
